// Differential checks of TcoAck-pbo.js against Lean, generated by leanscript --check
import * as M from "./TcoAck-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("ack2(0, 0)", () => M.ack2(0, 0), "1", false);
check("ack2(0, 2)", () => M.ack2(0, 2), "3", false);
check("ack2(1, 1)", () => M.ack2(1, 1), "3", false);
check("ack2(2, 0)", () => M.ack2(2, 0), "3", false);
check("ack2(0, 13)", () => M.ack2(0, 13), "14", false);
check("ack2(1, 5)", () => M.ack2(1, 5), "7", false);
check("ack2(2, 2)", () => M.ack2(2, 2), "7", false);
check("AckWithoutStackButUsingCantorPairing$pair(0, 0)", () => M.AckWithoutStackButUsingCantorPairing$pair(0, 0), "0", false);
check("AckWithoutStackButUsingCantorPairing$pair(0, 2)", () => M.AckWithoutStackButUsingCantorPairing$pair(0, 2), "5", false);
check("AckWithoutStackButUsingCantorPairing$pair(1, 1)", () => M.AckWithoutStackButUsingCantorPairing$pair(1, 1), "4", false);
check("AckWithoutStackButUsingCantorPairing$pair(2, 0)", () => M.AckWithoutStackButUsingCantorPairing$pair(2, 0), "3", false);
check("AckWithoutStackButUsingCantorPairing$pair(0, 13)", () => M.AckWithoutStackButUsingCantorPairing$pair(0, 13), "104", false);
check("AckWithoutStackButUsingCantorPairing$pair(1, 5)", () => M.AckWithoutStackButUsingCantorPairing$pair(1, 5), "26", false);
check("AckWithoutStackButUsingCantorPairing$pair(2, 2)", () => M.AckWithoutStackButUsingCantorPairing$pair(2, 2), "12", false);
check("AckWithoutStackButUsingCantorPairing$pair(5, 1)", () => M.AckWithoutStackButUsingCantorPairing$pair(5, 1), "22", false);
check("AckWithoutStackButUsingCantorPairing$pair(13, 0)", () => M.AckWithoutStackButUsingCantorPairing$pair(13, 0), "91", false);
check("AckWithoutStackButUsingCantorPairing$pair(2, 13)", () => M.AckWithoutStackButUsingCantorPairing$pair(2, 13), "133", false);
check("AckWithoutStackButUsingCantorPairing$pair(5, 5)", () => M.AckWithoutStackButUsingCantorPairing$pair(5, 5), "60", false);
check("AckWithoutStackButUsingCantorPairing$pair(13, 2)", () => M.AckWithoutStackButUsingCantorPairing$pair(13, 2), "122", false);
check("AckWithoutStackButUsingCantorPairing$pair(13, 13)", () => M.AckWithoutStackButUsingCantorPairing$pair(13, 13), "364", false);

console.log(`TcoAck-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
